window.kbPageData["views/entry/k-798eb73977307bd2"] = {"key":"entry/k-798eb73977307bd2","state":{"route":"entry/k-798eb73977307bd2"},"node":{"id":"k-798eb73977307bd2","mode":"k","title":"等差数列的公差","type":"概念与词义","domain":"数学","reading":"","intro":"","priority":100,"aliases":["等差数列的相邻两项之差恒等于公差"],"qs":["江苏 2024 C类 行测#56"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"公差是等差数列中每一项减去它的前一项所得的固定差值。","review":{"definition":"公差是等差数列中每一项减去它的前一项所得的固定差值。","explanation":"按年龄从小到大排列，四人的平均年龄为35.5岁，位于中间两个年龄之间。47岁高于平均年龄，只可能排在最大的两项中，而各选项均给出大于47岁的最大年龄，因此47岁是第二大年龄。它比第三大年龄24岁大23岁，再加一个公差即得最大年龄70岁，对应B项。","references":[],"evidence":"47-24=23岁","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 C类 行测#56":{"paper":"江苏 2024 C类 行测","n":56,"mod":"数量关系","src":["3f1ec77ae8a18519b57e.pdf",10],"asrc":["02d6b49839583bdaf297.pdf",16],"card":"f190d9142902f58b72e2f122","links":[{"id":"k-798eb73977307bd2","role":"解题依据","why":"由中间两项的年龄差得到公差，再从第二大项推到最大项。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-798eb73977307bd2":[["江苏 2024 C类 行测#56"]]}};
